313	    if (!isPasswordlessEnabled) return;
314	    const result = await handlePasswordlessLogin(emailValue);
315	    if (result.success) {
316	      onClose();
317	      // Brief delay lets the drawer finish its exit transition before OTP modal mounts.
318	      setTimeout(() => setIsOtpAuthOpen(true), DRAWER_ANIMATION_DELAY_MS);
319	    }
320	    return result;
321	  };
