360	              hint: 'google',
361	              // Social IDP redirects are browser-only — window.location.origin is always available
362	              // here. useAppOrigin() calls useServerContext() which returns undefined in browser,
363	              // causing a destructuring throw; reading the origin directly avoids the SSR hook.
