import { describe, test, expect, vi, beforeEach } from 'vitest';
import { act } from '@testing-library/react';
import type { ShopperBasketsV2Types } from 'commerce-sdk-isomorphic';
import { renderHookWithQueryClient } from 'app/test-utils/renderWithProviders';
import { useCartMergeAndCap, type CartCapBasket } from './useCartMergeAndCap';

const { mockMutateAsync, mockUseIsMutating } = vi.hoisted(() => ({
  mockMutateAsync: vi.fn(),
  mockUseIsMutating: vi.fn(() => 0),
}));

vi.mock('@salesforce/commerce-sdk-react', () => ({
  useShopperBasketsV2Mutation: () => ({ mutateAsync: mockMutateAsync }),
}));

vi.mock('@tanstack/react-query', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@tanstack/react-query')>();
  return { ...actual, useIsMutating: mockUseIsMutating };
});

const makeLineItem = (
  overrides: Partial<ShopperBasketsV2Types.BasketProductItem> = {},
): ShopperBasketsV2Types.BasketProductItem => ({
  itemId: 'item-1',
  productId: 'product-1',
  quantity: 1,
  ...overrides,
});

const makeBasket = (
  productItems: ShopperBasketsV2Types.BasketProductItem[],
  overrides: Partial<CartCapBasket> = {},
): CartCapBasket => ({
  basketId: 'basket-1',
  lastModified: '2026-09-20T00:00:00.000Z',
  productItems,
  ...overrides,
});

describe('PROBE: stale isMutating closure', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockUseIsMutating.mockReturnValue(0);
    mockMutateAsync.mockResolvedValue({});
  });

  test('capBasketQuantities captured while isMutating=0, then a real mutation starts BEFORE it is invoked (no rerender of this hook instance) — does the guard still catch it?', async () => {
    const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
    // Capture the function reference NOW, while isMutating() reads 0 (this mirrors
    // useWishlistAuthDrawer.ts's real shape: capBasketQuantities is captured at the render
    // when isRegistered flips, then invoked later, asynchronously, inside mergeBasket's
    // onSuccess — with no guarantee this hook instance re-renders in between).
    const capturedCapFn = result.current.capBasketQuantities;

    // Simulate "an unrelated mutation starts elsewhere in the app" happening AFTER this
    // hook's render captured isMutating=0, but BEFORE capturedCapFn is actually invoked —
    // without forcing a rerender of THIS hook instance (no `rerender()` call), since the real
    // useWishlistAuthDrawer.ts effect closure has no mechanism to force itself to rerender
    // between capturing capBasketQuantities and mergeBasket's onSuccess firing.
    mockUseIsMutating.mockReturnValue(1);

    const basket = makeBasket([makeLineItem({ quantity: 5 })]);
    const outcome = await act(async () => capturedCapFn(basket));

    // eslint-disable-next-line no-console
    console.log('PROBE OUTCOME:', JSON.stringify(outcome), 'mutateAsync calls:', mockMutateAsync.mock.calls.length);

    // This assertion intentionally states what a LIVE guard would do, to see whether the
    // real implementation matches it or not.
    expect(outcome).toEqual({ status: 'skipped', reason: 'mutation-in-flight' });
  });

  test('control: capBasketQuantities captured AFTER isMutating flips to 1 (a real rerender happens first) — guard correctly catches it', async () => {
    const { result, rerender } = renderHookWithQueryClient(() => useCartMergeAndCap());
    mockUseIsMutating.mockReturnValue(1);
    rerender();
    const freshCapFn = result.current.capBasketQuantities;

    const basket = makeBasket([makeLineItem({ quantity: 5 })]);
    const outcome = await act(async () => freshCapFn(basket));

    expect(outcome).toEqual({ status: 'skipped', reason: 'mutation-in-flight' });
  });
});
EOF
